#include <iostream>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    long long l, r, k;
    std::cin >> l >> r >> k;

    // Multiples of k in [1, R], minus multiples of k in [1, L-1].
    std::cout << (r / k - (l - 1) / k) << '\n';
}
